import fs from 'node:fs';
const root=new URL('../',import.meta.url);
const lessons=Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0')).map(n=>JSON.parse(fs.readFileSync(new URL(`content/proverb-compass/proverb-${n}.json`,root))));
const data=Object.fromEntries(lessons.map(l=>[l.id,{...l,items:l.items.map(({source,...item})=>item)}]));
const keys=Object.fromEntries(lessons.flatMap(l=>l.items.slice(0,l.scoredCount??50).map(q=>[q.id,q.options.find(o=>o.correct).text])));
const outputs={
 'proverb-compass-data.mjs':`// Generated by tools/build-proverb-compass.mjs from the approved review JSON.\nexport const PROVERB_COMPASS = ${JSON.stringify(data)};\n`,
 'workers/proverb-system/src/curated-catalog.js':`// Generated by tools/build-proverb-compass.mjs. Legacy catalogue stays valid.\nexport const CURATION_VERSION = "2026-10-28.1";\nexport const CURATED_ANSWERS = Object.freeze(${JSON.stringify(keys,null,2)});\n`
};
for(const [name,text] of Object.entries(outputs)){
 const file=new URL(name,root);if(process.argv.includes('--check')){if(fs.readFileSync(file,'utf8')!==text)throw Error(`Stale ${name}`);}else fs.writeFileSync(file,text);
}
console.log(`Built ${lessons.length} guides, ${lessons.reduce((n,l)=>n+l.items.length,0)} items, ${Object.keys(keys).length} server-validated keys.`);
